    <?php if ($actions): ?><form method="post" action="<?= $e($url('admin/consultancy/review')) ?>" class="form-stack"><?= Ui::csrf() ?><input type="hidden" name="id" value="<?= $e($c['id']) ?>"><div class="field"><label for="note">Note to consultancy <span class="label-note">optional</span></label><input id="note" name="note" maxlength="255" placeholder="Shown on their account page"></div><div class="review-actions"><?php foreach ($actions as $action => $label): ?><button class="button <?= in_array($action, ['approve', 'reactivate'], true) ? 'primary' : 'secondary danger-text' ?>" type="submit" formaction="<?= $e($url('admin/consultancy/review?do=' . $action)) ?>"><?= $e($label) ?></button><?php endforeach; ?></div></form><?php endif; ?>
</aside>
